class Solution {
public:
    string makeGood(string s) {
        string st;
        for (int i = 0; i < (int)s.size(); i++) {
            if (!st.empty() && st.back() != s[i] && tolower(st.back()) == tolower(s[i])) st.pop_back();
            else st.push_back(s[i]);
        }
        return st;
    }
};
